password_keywords := {"password", "passwd", "pwd", "secret", "passphrase", "credential", "auth_token", "api_key", "api_secret", "access_key", "secret_key", "private_key", "encryption_key", "master_password", "admin_password", "root_password", "service_password", "database_password", "db_password", "ldap_password", "smtp_password"}

# Check if a name indicates a password/credential field
is_password_field(name) {
    lower_name := lower(name)
    some kw in password_keywords
    contains(lower_name, kw)
}

# Check if value is empty string or null/undef
is_empty_value(value) {
    value.ir_type == "String"
    trim(value.value, "\t\n\r ") == ""
}

is_empty_value(value) {
    value.ir_type == "Null"
}

is_empty_value(value) {
    value.ir_type == "Undef"
}

# Recursively check nested structures for empty password fields
check_nested_empty_password(node) {
    walk(node, [_, n])
    n.ir_type == "Hash"
    key := [k | k := n.value[_][0]][0]
    val := [v | v := n.value[_][1]][0]
    key.ir_type == "String"
    is_password_field(key.value)
    is_empty_value(val)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]
    is_password_field(var.name)
    is_empty_value(var.value)

    result := {
        "type": "sec_empty_pass",
        "element": var,
        "path": parent.path,
        "description": "Empty password in configuration file - Password or credential fields should not be assigned empty values. (CWE-258)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    aus := glitch_lib.all_atomic_units(parent)
    au := aus[_]
    attrs := glitch_lib.all_attributes(au)
